def solve(grid):
    h,w=len(grid),len(grid[0])
    occ={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0}
    tiles=[]
    for r in range(h-1):
        for c in range(w-1):
            sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if sq<=occ: tiles.append((sq,1))
            colors={(r,c):2,(r,c+1):4,(r+1,c):3,(r+1,c+1):5}
            for missing,col in colors.items():
                shape=sq-{missing}
                if shape<=occ: tiles.append((shape,col))
    bycell={p:[] for p in occ}
    for shape,col in tiles:
        for p in shape: bycell[p].append((shape,col))
    def rec(rem):
        if not rem: return []
        p=min(rem,key=lambda q:sum(shape<=rem for shape,_ in bycell[q]))
        for shape,col in bycell[p]:
            if shape<=rem:
                tail=rec(rem-shape)
                if tail is not None:return [(shape,col)]+tail
        return None
    pieces=rec(occ)
    if pieces is None: raise ValueError('no tile')
    result=[[0]*w for _ in range(h)]
    for shape,col in pieces:
        for r,c in shape:result[r][c]=col
    return result
