    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= occupied:
                tiles.append((square, 1))
            # Color each three-cell L by the missing corner.
            corner_colors = {
                (r, c): 2,          # missing top-left
                (r, c + 1): 4,      # missing top-right
                (r + 1, c): 3,      # missing bottom-left
                (r + 1, c + 1): 5,  # missing bottom-right
            }
            for missing, color in corner_colors.items():
                shape = square - {missing}
                if shape <= occupied:
                    tiles.append((shape, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in tiles:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        # Choose the most constrained uncovered cell first.
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    pieces = cover(occupied)
    if pieces is None:
        raise ValueError("Input cannot be tiled by 2x2 squares and L triominoes")
    result = [[0] * w for _ in range(h)]
    for shape, color in pieces:
        for r, c in shape:
            result[r][c] = color
    return result
